<?php require_once __DIR__.'/../config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo=db();if(($_POST['action']??'')==='settings'){$up=$pdo->prepare('INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$up->execute(['whatsapp_number',preg_replace('/\D/','',$_POST['whatsapp_number']??'')]);flash('success','Konfigurasi WhatsApp disimpan.');}if(($_POST['action']??'')==='bank'){$pdo->prepare('UPDATE bank_accounts SET bank_name=?,account_name=?,account_number=? WHERE id=?')->execute([trim($_POST['bank_name']),trim($_POST['account_name']),trim($_POST['account_number']),(int)$_POST['id']]);flash('success','Rekening bank disimpan.');}redirect('admin/settings.php');}$bank=db()->query('SELECT * FROM bank_accounts WHERE is_active=1 LIMIT 1')->fetch();$adminTitle='Bank & WhatsApp configuration';require __DIR__.'/_header.php';?><div class="grid md:grid-cols-2 gap-6"><form class="bg-white p-6" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="settings"><h2 class="serif text-2xl">WhatsApp</h2><p class="text-sm text-slate-500">Nomor ini digunakan pada semua tombol konsultasi custom dan konfirmasi.</p><div class="field"><label>Nomor WhatsApp (format 628...)</label><input required name="whatsapp_number" value="<?=e(setting('whatsapp_number'))?>"></div><button class="btn gold">SAVE WHATSAPP</button></form><form class="bg-white p-6" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="bank"><input type="hidden" name="id" value="<?=$bank['id']??0?>"><h2 class="serif text-2xl">Bank account</h2><div class="field"><label>Bank</label><input required name="bank_name" value="<?=e($bank['bank_name']??'')?>"></div><div class="field"><label>Nama pemilik</label><input required name="account_name" value="<?=e($bank['account_name']??'')?>"></div><div class="field"><la